function nextDaily(minute, hour, from) {
  const today = new Date(Date.UTC(from.getUTCFullYear(), from.getUTCMonth(), from.getUTCDate(), hour, minute));
  if (today.getTime() <= from.getTime()) {
    return new Date(today.getTime() + 24 * 60 * 60 * 1000);
  }
  return today;
}

const from = new Date("2026-10-02T12:00:00Z");
console.log(nextDaily(45, 23, from).toISOString());
console.log(nextDaily(30, 2, from).toISOString());

