questions.solution:
function matches(field, value) {
  if (field === "*") return true;
  if (field.startsWith("*/")) return value % Number(field.slice(2)) === 0;
  if (field.includes("-")) {
    const [low, high] = field.split("-").map(Number);
    return value >= low && value <= high;
  }
  return Number(field) === value;
}

console.log(
  matches("*", 7),
  matches("*/15", 45),
  matches("*/15", 20),
  matches("1-5", 3),
  matches("9", 10),
);

