function runStarts(fireTimes, duration) {
  const starts = [];
  let busyUntil = -Infinity;
  for (const time of fireTimes) {
    if (time < busyUntil) continue;
    starts.push(time);
    busyUntil = time + duration;
  }
  return starts;
}

console.log(runStarts([0, 10, 20, 30, 40, 50, 60], 25));

