const sentDays = new Set();

function handleDigest(scheduledAt) {
  const day = scheduledAt.toISOString().slice(0, 10);
  if (sentDays.has(day)) return "skipped";
  sentDays.add(day);
  return "sent";
}

const monday = new Date("2026-10-05T09:00:00Z");
const tuesday = new Date("2026-10-06T09:00:00Z");
console.log(handleDigest(monday), handleDigest(monday), handleDigest(tuesday));

