questions.solution:
function restore(row, now, policy) {
  const due = new Date(row.remindAt);
  if (due.getTime() > now.getTime()) return due.toISOString();
  return policy === "run-once" ? now.toISOString() : "skipped";
}

const now = new Date("2026-10-02T12:00:00Z");
console.log(restore({ remindAt: "2026-10-02T08:00:00Z" }, now, "run-once")); // 2026-10-02T12:00:00.000Z
console.log(restore({ remindAt: "2026-10-02T08:00:00Z" }, now, "skip")); // skipped
console.log(restore({ remindAt: "2026-10-12T08:00:00Z" }, now, "skip")); // 2026-10-12T08:00:00.000Z

